imageHint: "Sarektjakka mountain massif in Sarek National Park",
    descriptionAdvanced: {
      de: "Das Sarektjåkkå-Massiv liegt im Herzen des Sarek-Nationalparks in Schwedisch-Lappland und beherbergt den zweithöchsten Berg Schwedens. Das Massiv ist durch seine gewaltige Ausdehnung und vier markante Gipfel geprägt, von denen der Stortoppen mit 2089 Metern der höchste ist. Das Gebiet gilt als eine der entlegensten und anspruchsvollsten Wildnisregionen Europas, da es im gesamten Nationalpark keine markierten Wege, Brücken oder Hütten gibt. Geologisch besteht das Massiv aus hartem Amphibolit und ist von zahlreichen Gletschern umgeben, darunter der imposante Mikka-Gletscher. Sarektjåkkå ist Teil des UNESCO-Welterbes Laponia und hat eine tiefe kulturelle Bedeutung für das Volk der Samen, die die Region seit Jahrtausenden für die Rentierwirtschaft nutzen. Erfahrene Alpinisten schätzen das Sarektjåkkå wegen seiner Isolation und der unberührten Natur, die eine absolute Selbstversorgung und hohe Navigationskenntnisse erfordert. Die Besteigung bietet eine der spektakulärsten Aussichten in den schwedischen Bergen, über tief eingeschnittene Täler wie das Rapadalen und zahllose Gipfel der Arktis.",
      hu: "A Sarektjåkkå-masszívum a svéd lappföldi Sarek Nemzeti Park szívében található, és Svédország második legmagasabb hegyének ad otthont. A masszívumot hatalmas kiterjedése és négy markáns csúcsa jellemzi, amelyek közül a Stortoppen a legmagasabb, 2089 méterrel. A területet Európa egyik legtávolabbi és legnagyobb kihívást jelentő vadonjaként tartják számon, mivel az egész nemzeti parkban nincsenek jelzett utak, hidak vagy menedékházak. Geológiailag a masszívum kemény amfibolitból áll, és számos gleccser veszi körül, köztük az impozáns Mikka-gleccser. A Sarektjåkkå az UNESCO Világörökség részét képező Laponia területéhez tartozik, és mély kulturális jelentőséggel bír a számi nép számára, akik évezredek óta használják a régiót rénszarvastartásra. A tapasztalt hegymászók az elszigeteltsége és az érintetlen természete miatt értékelik a Sarektjåkkåt, amely teljes önellátást és magas szintű tájékozódási képességet igényel. A csúcs elérése az egyik leglátványosabb kilátást nyújtja a svéd hegyekben, rálátással az olyan mélyen bevágott völgyekre, mint a Rapadalen, és számtalan sarkvidéki csúcsra.",
      ro: "Masivul Sarektjåkkå este situat în inima Parcului Național Sarek din Laponia suedeză și găzduiește al doilea cel mai înalt munte din Suedia. Masivul este caracterizat prin extinderea sa vastă și prin patru vârfuri proeminente, dintre care Stortoppen este cel mai înalt, având 2089 de metri. Regiunea este considerată una dintre cele mai îndepărtate și solicitante zone de sălbăticie din Europa, deoarece în întregul parc național nu există poteci marcate, poduri sau cabane. Din punct de vedere geologic, masivul este format din amfibolit dur și este înconjurat de numeroși ghețari, inclusiv impunătorul ghețar Mikka. Sarektjåkkå face parte din situl Patrimoniului Mondial UNESCO Laponia și are o semnificație culturală profundă pentru poporul Sami, care utilizează regiunea de milenii pentru creșterea renilor. Alpiniștii experimentați apreciază Sarektjåkkå pentru izolarea sa și natura virgină, care necesită autosuficiență totală și abilități avansate de navigare. Ascensiunea oferă una dintre cele mai spectaculoase vederi din munții suedezi, peste văi adânci precum Rapadalen și nenumărate vârfuri arctice.",
      en: "The Sarektjåkkå massif is situated in the heart of Sarek National Park in Swedish Lapland and contains Sweden's second-highest mountain. The massif is defined by its massive scale and four distinct peaks, the highest being Stortoppen at 2089 meters. This area is regarded as one of Europe's most remote and challenging wildernesses, as the entire national park lacks marked trails, bridges, or permanent mountain huts. Geologically composed of durable amphibolite, the massif is flanked by several glaciers, including the impressive Mikka Glacier. Sarektjåkkå is part of the Laponia UNESCO World Heritage site and holds deep cultural importance for the Sámi people, who have managed reindeer in the region for thousands of years. Experienced mountaineers value Sarektjåkkå for its isolation and pristine environment, which demands total self-sufficiency and high-level navigation skills. Reaching its heights offers some of the most spectacular vistas in the Swedish mountains, looking out over deep-cut valleys like Rapadalen and countless Arctic peaks.",
      es: "El macizo de Sarektjåkkå se encuentra en lo profundo del Parque Nacional Sarek y alberga algunos de los picos más remotos y exigentes de los Alpes escandinavos.",
      pt: "O maciço de Sarektjåkkå encontra-se nas profundezas do Parque Nacional Sarek e alberga alguns dos picos mais remotos e exigentes dos Alpes escandinavos.",
      fr: "Le massif de Sarektjåkkå se situe au plus profond du parc national de Sarek et abrite certains des sommets les plus reculés et les plus exigeants des Alpes scandinaves.",
    },
