imageHint: "Akka mountain massif above lake Akkajaure",
    descriptionAdvanced: {
      de: "Das Akka-Massiv, oft als die \"Königin von Lappland\" bezeichnet, ist ein markanter Gebirgskomplex im Nationalpark Stora Sjöfallet in der Provinz Norrbottens län. Mit dem Stortoppen erreicht es eine Höhe von 2015 Metern über dem Meeresspiegel und gehört damit zu den höchsten Erhebungen Schwedens außerhalb des Kebnekaise-Massivs. Geologisch besteht das Gebirge aus steilen Gipfeln und tiefen Gletschertälern, wobei insgesamt zehn verschiedene Gletscher die Landschaft prägen. Für die indigene Bevölkerung der Samen besitzt der Berg eine tiefe spirituelle Bedeutung und gilt als heiliger Ort. Das Massiv ist Teil des UNESCO-Welterbes Laponia, das sowohl für seine einzigartige Natur als auch für seine kulturelle Bedeutung geschützt ist. Aufgrund seiner isolierten Lage und der weiten Sichtbarkeit über die nordschwedische Tundra ist Akka ein wichtiges Orientierungsmerkmal für Wanderer und Bergsteiger in der Region.",
      hu: "Az Akka-masszívum, amelyet gyakran „Lappföld királynőjeként” emlegetnek, egy impozáns hegycsoport a Stora Sjöfallet Nemzeti Parkban, Norrbotten megyében. Legmagasabb pontja, a Stortoppen 2015 méterrel magasodik a tengerszint fölé, ezzel Svédország egyik legjelentősebb hegycsúcsa a Kebnekaise után. A masszívum tizenkét különálló csúcsból és tíz gleccserből áll, ami rendkívül tagolt és vadregényes alpesi tájat kölcsönöz a vidéknek. Az őshonos számi nép számára az Akka szent hely, amely mélyen gyökerezik spirituális hagyományaikban és mondavilágukban. A terület a Lapónia világörökségi helyszín része, amelyet az UNESCO a természeti értékek és a rénszarvastartó kultúra megőrzése érdekében védetté nyilvánított. Távoli elhelyezkedése és a környező tundrából való hirtelen kiemelkedése miatt a hegy a túrázók és hegymászók egyik legkedveltebb, de próbára tevő célpontja.",
      ro: "Masivul Akka, supranumit adesea „Regina Laponiei”, este un complex montan impunător situat în Parcul Național Stora Sjöfallet din comitatul Norrbotten. Vârful său principal, Stortoppen, atinge o altitudine de 2015 metri peste nivelul mării, fiind unul dintre cei mai înalți munți din Suedia. Din punct de vedere geologic, masivul este format din douăsprezece vârfuri și zece ghețari, oferind un peisaj alpin spectaculos care domină tundra înconjurătoare. Pentru populația indigenă Sami, muntele are o semnificație spirituală profundă, fiind considerat un loc sacru în mitologia lor locală. Masivul face parte din regiunea Laponia, inclusă în patrimoniul mondial UNESCO pentru valoarea sa naturală și culturală excepțională. Datorită izolării sale și a vizibilității de la distanțe mari, Akka rămâne un punct de reper esențial pentru orientarea în sălbăticia nordului arctic suedez.",
      en: "The Akka massif, frequently referred to as the \"Queen of Lapland,\" is an impressive mountain complex situated within the Stora Sjöfallet National Park in Norrbotten County. Its highest peak, Stortoppen, rises to an elevation of 2,015 meters above sea level, making it one of the most prominent landmarks in the Swedish Arctic. The massif is characterized by its twelve distinct peaks and ten glaciers, showcasing a rugged alpine landscape that contrasts sharply with the surrounding lowlands. To the indigenous Sami people, Akka is a sacred site, deeply embedded in their spiritual traditions and oral history. As part of the Laponian Area, a UNESCO World Heritage site, it is recognized for both its outstanding natural beauty and its cultural significance to the reindeer-herding communities. The mountain remains a challenging destination for experienced mountaineers due to its remote location and unpredictable subarctic weather conditions.",
      es: "Conocido como la Reina de Laponia, el macizo de Akka domina el paisaje junto al gran lago Akkajaure con sus característicos picos nevados.",
      pt: "Conhecido como a Rainha da Lapónia, o maciço de Akka domina a paisagem junto ao grande lago Akkajaure com os seus característicos picos nevados.",
      fr: "Connu comme la Reine de Laponie, le massif d'Akka domine le paysage près du grand lac Akkajaure avec ses sommets enneigés caractéristiques.",
    },
    factsAdvanced: {
      de: ["Höhe von 2015 Metern am Stortoppen", "Teil des UNESCO-Welterbes Laponia", "Beherbergt zehn verschiedene Gletscher", "Besteht aus insgesamt zwölf Gipfeln", "Heiliger Berg des Volkes der Samen", "Gelegen im Nationalpark Stora Sjöfallet"],
      hu: ["A Stortoppen magassága 2015 méter", "Az UNESCO Lapónia világörökség része", "Tíz gleccser található a területén", "Tizenkét különálló csúcsból áll", "A számi nép szent hegyként tiszteli", "A Stora Sjöfallet Nemzeti Parkban fekszik"],
      ro: ["Altitudinea vârfului Stortoppen este de 2015 m", "Inclus în patrimoniul mondial UNESCO Laponia", "Găzduiește un număr de zece ghețari", "Masivul este compus din douăsprezece vârfuri", "Considerat munte sacru de către poporul Sami", "Situat în Parcul Național Stora Sjöfallet"],
      en: ["Height of 2,015 meters at Stortoppen", "Part of the UNESCO World Heritage Site Laponia", "Contains ten distinct glaciers", "Comprises a total of twelve peaks", "Sacred mountain for the indigenous Sami people", "Located within Stora Sjöfallet National Park"],
      es: ["Altura: 2015 m", "Apodo: Reina", "12 picos en el macizo", "Ubicación: Norrbotten"],
      pt: ["Altura: 2015 m", "Apelido: Rainha", "12 picos no maciço", "Localização: Norrbotten"],
      fr: ["Hauteur : 2015 m", "Surnom : Reine", "12 sommets dans le massif", "Localisation : Norrbotten"],
    },
