      hu: "A Dundret-hegy Lappföldön, Gällivare közelében található. Lapos tetejéről és az éjféli napra nyíló kiváló kilátásáról ismert.",
      ro: "Muntele Dundret este situat lângă Gällivare, în Laponia. Este cunoscut pentru vizibilitatea excelentă a soarelui de la miezul nopții și vârful său plat.",
