      hu: ["Magassága 1589 méter", "Dél-Lappföld legmagasabb hegye", "Egy 86 000 hektáros rezervátum része", "Kvarcitból és csillámpalából áll"],
      ro: ["Înălțime 1589 metri", "Cel mai înalt munte din sudul Laponiei", "Parte a unei rezervații de 86.000 hectare", "Compus din cuarțit și micasist"],
      en: ["Height 1589 meters", "Highest mountain in southern Lapland", "Part of an 86,000-hectare reserve", "Composed of quartzite and mica schist"],
      es: ["Altura 1589 metros", "Montaña más alta en el sur de Laponia", "Parte de una reserva de 86.000 hectáreas", "Compuesta de cuarcita y esquisto de mica"],
      pt: ["Altura 1589 metros", "Montanha mais alta no sul da Lapónia", "Parte de uma reserva de 86.000 hectares", "Composta de quartzito e xisto micáceo"],
