      en: ["Highest peak reaches 1,589 meters", "Nature reserve covers 86,000 hectares", "Located within Vilhelmina Municipality", "Consists of geological mica schist", "Part of the Scandinavian Mountain range", "Home to the rare glacier crowfoot"],
