      hu: ["Magassága 304 méter", "A régió legnagyobb táblahegye", "Üledékes kőzetből áll, diabáz sapkával", "Skövde városa a hegy lábánál fekszik"],
      ro: ["Înălțime 304 metri", "Cel mai mare munte tabular din regiune", "Format din roci sedimentare cu vârf de diabaz", "Orașul Skövde este situat la poalele sale"],
      en: ["Height 304 meters", "Largest table mountain in the region", "Consists of sedimentary rock with a diabase cap", "The city of Skövde lies at its foot"],
      es: ["Altura 304 metros", "La mesa más grande de la región", "Compuesto de roca sedimentaria con capa de diabasa", "Skövde se encuentra al pie de la montaña"],
      pt: ["Altura 304 metros", "A maior mesa da região", "Composto por rocha sedimentar com capa de diabásio", "Skövde situa-se no sopé da montanha"],
