      hu: "Az Omberg egy jellegzetes röghegység a Vättern-tó keleti partján. Meredeken emelkedik ki a környező síkságból, pazar kilátást nyújtva.",
      ro: "Omberg este un horst distinct situat pe coasta de est a lacului Vättern. Se ridică abrupt din câmpia înconjurătoare și oferă priveliști spectaculoase.",
