      hu: ["Magassága 188 méter", "Gneisz kőzetből épül fel", "Számos tengeri barlang a parton", "Itt található a Kullen világítótorony"],
      ro: ["Înălțime 188 metri", "Compus din gnais", "Numeroase peșteri marine pe coastă", "Locația farului Kullen"],
      en: ["Height 188 meters", "Composed of gneiss", "Numerous sea caves along the coast", "Location of the Kullen lighthouse"],
      es: ["Altura 188 metros", "Compuesto de gneis", "Numerosas cuevas marinas en la costa", "Ubicación del faro Kullen"],
      pt: ["Altura 188 metros", "Composto de gnaisse", "Numerosas cavernas marinhas na costa", "Localização do farol Kullen"],
