imageHint: "Kullaberg rocky cliffs and sea",
    descriptionAdvanced: {
      de: "Kullaberg ist ein Gebirgsrücken und Naturschutzgebiet auf einer Halbinsel im Nordwesten von Schonen, das steil in den Öresund und das Kattegat abfällt. Die geologische Formation besteht hauptsächlich aus Gneis und wurde durch tektonische Hebungen und die anschließende Brandungserosion der Meere geformt. Die Küstenlinie ist von zahlreichen Grotten und Höhlen geprägt, wie der bekannten Kullamannen-Höhle, die seit der Steinzeit von Menschen genutzt wurden. Auf dem höchsten Punkt des Rückens steht der Leuchtturm Kullen fyr, der mit seinem Lichtsignal 78,5 Meter über dem Meeresspiegel eines der wichtigsten Navigationslichter in den schwedischen Gewässern ist. Das Gebiet beherbergt eine außergewöhnliche Flora und Fauna, darunter seltene Orchideenarten und eine bedeutende Population von Schweinswalen vor der Küste. Wanderwege führen entlang der Klippen und bieten weite Ausblicke bis zur dänischen Küste auf der gegenüberliegenden Seite des Sunds.",
      hu: "A Kullaberg egy látványos sziklafalakkal övezett félsziget és természetvédelmi terület Skåne északnyugati részén, amely az Öresund és a Kattegat találkozásánál nyúlik a tengerbe. Geológiailag egy tektonikus kiemelkedés, amely főként gneiszből épül fel, és meredek partjait a tenger hullámai formálták évezredeken keresztül. A partvonal mentén több mint húsz barlang található, amelyek közül néhányban kőkorszaki emberi jelenlét nyomait is felfedezték a régészek. A félsziget legmagasabb pontján áll a Kullen világítótorony, amely Skandinávia egyik legrégebbi és legfényesebb navigációs pontja, fénye több mint 50 kilométerre ellátszik. A terület különleges mikroklímával rendelkezik, amely lehetővé teszi ritka orchideafajok és délebbi növények megtelepedését a sziklák között. A környező vizekben gyakran megfigyelhetők barna delfinek, amelyek a part közelségében vadásznak.",
      ro: "Kullaberg este o creastă muntoasă și o rezervație naturală situată pe o peninsulă din nord-vestul Scaniei, prăbușindu-se abrupt în apele strâmtorii Öresund și ale mării Kattegat. Formațiunea geologică este compusă în principal din gnais și a fost creată prin mișcări tectonice, fiind ulterior modelată de forța erozivă a valurilor. Coasta este presărată cu numeroase peșteri marine, cum ar fi Peștera Kullamannen, care au fost folosite de oameni încă din epoca pietrei pentru adăpost. În cel mai înalt punct al rezervației se află farul Kullen, unul dintre cele mai importante puncte de navigație din Suedia, situat la o altitudine de 78,5 metri deasupra mării. Zona este celebră pentru biodiversitatea sa, oferind habitat pentru specii rare de orhidee și fiind un punct de observație excelent pentru marsuinii care înoată în apropierea țărmului. Traseele de drumeție oferă vederi spectaculoase până la coasta daneză.",
      en: "Kullaberg is a rugged peninsula and nature reserve in northwestern Scania, characterized by steep cliffs that drop sharply into the Öresund and Kattegat seas. The geological formation is a horst primarily composed of gneiss, shaped by tectonic shifts and millennia of marine erosion. The coastline features over twenty sea caves, including the well-known Kullamannen cave, where archaeological finds indicate human presence dating back to the Stone Age. At the peninsula's highest point sits the Kullen Lighthouse, one of Sweden's oldest and most powerful navigation aids, positioned 78.5 meters above sea level. The area boasts a unique microclimate that supports rare orchids and diverse birdlife, while the surrounding waters are a vital habitat for harbor porpoises. Extensive hiking trails wind along the ridge, providing panoramic views across the strait to the Danish coastline.",
      es: "Kullaberg en Escania es una dramática cresta costera con acantilados escarpados, cuevas y una flora y fauna marina única.",
      pt: "Kullaberg na Escânia é uma crista costeira dramática com penhascos íngremes, cavernas e uma flora e fauna marinha única.",
      fr: "Kullaberg, en Scanie, est une crête côtière spectaculaire avec des falaises abruptes, des grottes et une flore et une faune marines uniques.",
    },
    factsAdvanced: {
      de: ["Der Leuchtturm Kullen fyr steht 78,5 Meter über dem Meeresspiegel.", "An der Küste von Kullaberg befinden sich mehr als 20 Grotten.", "Geologisch handelt es sich um einen tektonischen Horst aus Gneis.", "Archäologen fanden in den Höhlen Werkzeuge aus der Steinzeit.", "Die Gewässer vor Kullaberg sind ein Schutzgebiet für Schweinswale.", "Der Gebirgsrücken erstreckt sich über eine Länge von etwa 8 Kilometern."],
      hu: ["A Kullen világítótorony a tengerszint felett 78,5 méteres magasságban áll.", "A félsziget partvonala mentén több mint 20 tengeri barlang található.", "Geológiailag egy prekambriumi gneiszből álló tektonikus rög.", "A barlangokban végzett ásatások kőkorszaki települések nyomait tárták fel.", "A környező vizek a barna delfinek (marsuinok) fontos élőhelyei.", "A legmagasabb pont, a Håkull, 187 méterrel magasodik a tenger fölé."],
      ro: ["Farul Kullen este situat la o altitudine de 78,5 metri deasupra mării.", "Există peste 20 de peșteri marine accesibile de-a lungul coastei.", "Formațiunea geologică principală este un horst tectonic format din gnais.", "S-au descoperit urme de locuire umană datând din paleolitic și mezolitic.", "Zona marină adiacentă este protejată pentru conservarea marsuinilor.", "Traseele de drumeție acoperă o lungime totală de peste 15 kilometri."],
      en: ["The Kullen Lighthouse is positioned 78.5 meters above sea level.", "More than 20 sea caves are located along the rocky coastline.", "Geologically, it is a tectonic horst composed of Precambrian gneiss.", "Stone Age tools and settlements have been discovered in the caves.", "The waters around the peninsula are a protected habitat for porpoises.", "The highest point of the ridge, Håkull, reaches 187 meters in elevation."],
      es: ["Altura: 188 m", "Ubicación: Escania", "Reserva natural", "Cuevas conocidas"],
      pt: ["Altura: 188 m", "Localização: Escânia", "Reserva natural", "Cavernas conhecidas"],
      fr: ["Hauteur : 188 m", "Localisation : Scanie", "Réserve naturelle", "Grottes connues"],
    },
