      de: "Der Hovärken ist ein markanter Berg bei Lofsdalen. Er bietet einen weiten Rundblick über die Wildnis von Härjedalen und ist ein Zentrum für Bergsport.",
      hu: "A Hovärken egy jellegzetes hegy Lofsdalen közelében. Pazar körpanorámát nyújt Härjedalen vadonjára, és a hegyi sportok központja.",
