      de: "Der Tjåmuhas ist ein Berg in der Nähe von Abisko, der für seine interessante Geologie bekannt ist. Er bietet einen spektakulären Blick auf das 'Tor von Lappland' (Lapporten).",
      hu: "A Tjåmuhas egy Abisko közelében található hegy, amely érdekes geológiájáról ismert. Látványos kilátást nyújt a 'Lappföld kapujára' (Lapporten).",
      ro: "Tjåmuhas este un munte situat lângă Abisko, cunoscut pentru geologia sa interesantă. Oferă o vedere spectaculoasă asupra „Porții Laponiei” (Lapporten).",
