      en: ["Tjåmuhas stands at an elevation of 1,743 meters.", "It is located in Swedish Lapland, near Abisko National Park.", "The mountain overlooks the scenic Lake Alesjaure.", "Geologically, it consists of metamorphic gneiss and schist.", "The area is a traditional summer grazing site for reindeer.", "The summit is a popular destination for experienced off-trail hikers."],
