      ro: "Înălțimile Glava sunt o regiune împădurită deluroasă în vestul Värmland. Sunt caracterizate prin văi adânci și numeroase lacuri mici.",
      en: "The Glava Heights are a hilly, forested region in western Värmland. They are defined by deeply incised valleys and numerous small lakes.",
      es: "Las colinas de Glava son una región forestal montañosa en el oeste de Värmland. Se caracterizan por valles profundamente cortados y numerosos lagos pequeños.",
