      es: ["Típica colina tipo Osz", "Capas sedimentarias", "Parte del paisaje de cuenca sueco", "Laderas suaves"],
      pt: ["Colina típica tipo Osz", "Camadas sedimentares", "Parte da paisagem de bacia sueca", "Encostas suaves"],
      fr: ["Colline typique de type Osz", "Couches sédimentaires", "Partie du paysage de bassin suédois", "Pentes douces"],
