      hu: ["Az 52 km széles Siljan-gyűrű kráterének része", "Becsapódás 377 millió évvel ezelőtt történt", "Körülbelül 170 méteres szintkülönbség a tótól", "Kilátás a 628 méter hosszú Långbryggan mólóra", "Paleozoikumi üledékes kőzetek kerültek felszínre", "Síterületként üzemel az 1960-as évek óta"],
      ro: ["Parte a craterului Inelul Siljan, de 52 km lățime", "Impact de meteorit acum 377 milioane de ani", "Diferență de nivel de circa 170 metri față de lac", "Vedere spre digul Långbryggan de 628 metri", "Roci sedimentare din paleozoic expuse la suprafață", "Funcționează ca zonă de schi din anii 1960"],
      en: ["Part of the 52 km wide Siljan Ring crater", "Meteorite impact occurred 377 million years ago", "Elevation rise of 170 meters from lake level", "Overlooks the 628-meter-long Långbryggan pier", "Exposes sedimentary rock from the Paleozoic era", "Active ski area since the 1960s"],
      es: ["Altura: aprox. 200 m", "Ubicación: Municipio de Rättvik, Dalarna", "Formación del lago Siljan: Impacto de meteorito hace 377 millones de años", "Festival anual: Rättviksbacken", "Tipo de roca: Granito y gneis", "Número de pistas de esquí: 4"],
      pt: ["Altura: aprox. 200 m", "Localização: Município de Rättvik, Dalarna", "Formação do lago Siljan: Impacto de meteorito há 377 milhões de anos", "Festival anual: Rättviksbacken", "Tipo de rocha: Granito e gnaisse", "Número de pistas de esqui: 4"],
