      ro: ["Ridicarea post-glaciară a solului de 9 mm pe an", "Situat în imediata apropiere a aeroportului Luleå", "Format din rocă de bază cristalină", "Fostă zonă militară restricționată în secolul XX", "Parte a peisajului de coastă din Norrbotten", "Punct de reper pentru arhipelagul Luleå"],
      en: ["Post-glacial land uplift of 9 mm per year", "Located in direct proximity to Luleå Airport", "Composed of crystalline bedrock", "Formerly a military restricted zone in the 20th century", "Part of the Norrbotten coastal landscape", "Navigation landmark for the Luleå archipelago"],
      es: ["Altura: aprox. 150 m s.n.m.", "Ubicación: Norrbotten, cerca de Luleå", "Edad de la roca: precámbrica (más de 1.000 millones de años)", "Parques eólicos: 3 en los alrededores", "Aeropuerto: Kallax (civil/militar)", "Distancia a Luleå: 5 km"],
      pt: ["Altura: aprox. 150 m s.n.m.", "Localização: Norrbotten, perto de Luleå", "Idade da rocha: pré-câmbrica (mais de 1.000 milhões de anos)", "Parques eólicos: 3 nos arredores", "Aeroporto: Kallax (civil/militar)", "Distância a Luleå: 5 km"],
