      pt: ["Cristas de morena", "Centro de desportos de inverno", "Altitude aprox. 200-250 metros", "Muitos lagos"],
      fr: ["Crêtes morainiques", "Centre de sports d'hiver", "Altitude env. 200-250 mètres", "Beaucoup de lacs"],
