      en: ["Elevations exceeding 300 meters above sea level", "Located by the 33 sq km Lake Åsunden", "Major winter sports center in southern Sweden", "Moraine deposits from the Weichsel glaciation", "Part of the historical Sjuhärad region", "Host to FIS Cross-Country World Cup events"],
