      hu: "A Söderåsen keleti része Skåne-ban egy sasbérc jellegű kiemelkedés, amely meredeken emelkedik ki a környező síkságból. A táj mélyen szabdalt.",
      ro: "Partea estică a Söderåsen din Skåne este o ridicare de tip horst care se înalță abrupt din câmpia din jur. Peisajul este adânc crestat.",
      en: "The eastern part of Söderåsen in Skåne is a horst-like elevation that rises steeply from the surrounding plain. The landscape is deeply incised.",
